/* Nxeon token contract — every preset, brand kit (.nxeon/brand.css) and section uses exactly these names.
   Default values = a neutral, accessible baseline. Override in :root (or [data-theme="dark"]). */
:root {
  /* color (semantic roles) */
  --color-bg: #fbfaf8;
  --color-surface: #ffffff;
  --color-surface-2: #f2f0ec;
  --color-text: #1d1b19;
  --color-muted: #5f5a54;
  --color-border: #e2ded7;
  --color-primary: #2747d8;
  --color-primary-contrast: #ffffff;
  --color-accent: #e0592a;
  --color-success: #1f7a4d;
  --color-danger: #c0322b;

  /* type */
  --font-display: ui-serif, Georgia, "Times New Roman", serif;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  --step--1: clamp(0.83rem, 0.8rem + 0.15vw, 0.9rem);
  --step-0: clamp(1rem, 0.96rem + 0.2vw, 1.125rem);
  --step-1: clamp(1.2rem, 1.1rem + 0.45vw, 1.45rem);
  --step-2: clamp(1.44rem, 1.28rem + 0.8vw, 1.9rem);
  --step-3: clamp(1.73rem, 1.45rem + 1.4vw, 2.5rem);
  --step-4: clamp(2.07rem, 1.6rem + 2.3vw, 3.3rem);
  --step-5: clamp(2.49rem, 1.7rem + 3.9vw, 4.6rem);
  --leading-tight: 1.1;
  --leading-body: 1.6;
  --measure: 68ch;

  /* space (4/8-pt scale) */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --space-8: 4rem;
  --space-9: 6rem;
  --space-10: 8rem;
  --section-pad: clamp(var(--space-8), 8vw, var(--space-10));
  --container: min(1140px, 92vw);

  /* shape + depth */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-pill: 999px;
  --shadow-sm: 0 1px 2px rgb(20 16 12 / 0.06);
  --shadow-md: 0 4px 14px rgb(20 16 12 / 0.08);
  --shadow-lg: 0 18px 40px rgb(20 16 12 / 0.12);

  /* motion */
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --dur: 200ms;
}
@media (prefers-reduced-motion: reduce) {
  :root { --dur: 0ms; }
}
/* Nxeon base: small reset + primitives used by the section library. Requires tokens.css (or a brand.css). */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
  font-size: var(--step-0);
  line-height: var(--leading-body);
  -webkit-font-smoothing: antialiased;
}
img, svg, video, canvas, picture { display: block; max-width: 100%; height: auto; }
input, button, textarea, select { font: inherit; color: inherit; }
h1, h2, h3, h4 { font-family: var(--font-display); line-height: var(--leading-tight); margin: 0 0 var(--space-4); text-wrap: balance; }
h1 { font-size: var(--step-5); }
h2 { font-size: var(--step-4); }
h3 { font-size: var(--step-2); }
p { margin: 0 0 var(--space-4); max-width: var(--measure); text-wrap: pretty; }
a { color: var(--color-primary); text-underline-offset: 0.18em; }
:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; border-radius: var(--radius-sm); }

.container { width: var(--container); margin-inline: auto; }
.section { padding-block: var(--section-pad); }
.muted { color: var(--color-muted); }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip-link { position: absolute; left: var(--space-4); top: -100px; z-index: 100; padding: var(--space-2) var(--space-4); background: var(--color-surface); color: var(--color-text); border-radius: var(--radius-md); }
.skip-link:focus { top: var(--space-4); }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
  min-height: 44px; padding: var(--space-3) var(--space-5);
  border: 1px solid transparent; border-radius: var(--radius-md);
  background: var(--color-primary); color: var(--color-primary-contrast);
  font-weight: 600; text-decoration: none; cursor: pointer;
  transition: transform var(--dur) var(--ease), background-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}
.btn:hover { box-shadow: var(--shadow-md); }
.btn:active { transform: translateY(1px); }
.btn--ghost { background: transparent; color: var(--color-text); border-color: var(--color-border); }
.btn--ghost:hover { background: var(--color-surface-2); box-shadow: none; }

.icon { width: 1.25em; height: 1.25em; flex: none; stroke: currentColor; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}
