import express from 'express';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { z } from 'zod';

/** Normalised mount path: '' (root) or '/preview/x' (no trailing slash). */
export const basePath = (process.env.BASE_PATH || '').replace(/\/+$/, '');

export class HttpError extends Error {
  constructor(status, code, message) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

// ---- example resource: in-memory items (replace with a real store) ----
const ItemInput = z.object({
  name: z.string().trim().min(1).max(200),
  done: z.boolean().default(false),
});
const ItemPatch = ItemInput.partial().refine((v) => Object.keys(v).length > 0, 'Provide at least one field');

function parse(schema, body) {
  const result = schema.safeParse(body);
  if (!result.success) {
    const msg = result.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ');
    throw new HttpError(400, 'validation_error', msg);
  }
  return result.data;
}

function itemsRouter() {
  const items = new Map();
  const router = express.Router();
  const find = (id) => {
    const item = items.get(id);
    if (!item) throw new HttpError(404, 'not_found', `Item ${id} not found`);
    return item;
  };

  router.get('/', (_req, res) => res.json({ data: [...items.values()] }));
  router.post('/', (req, res) => {
    const item = { id: randomUUID(), ...parse(ItemInput, req.body), createdAt: new Date().toISOString() };
    items.set(item.id, item);
    res.status(201).json({ data: item });
  });
  router.get('/:id', (req, res) => res.json({ data: find(req.params.id) }));
  router.patch('/:id', (req, res) => {
    const item = { ...find(req.params.id), ...parse(ItemPatch, req.body) };
    items.set(item.id, item);
    res.json({ data: item });
  });
  router.delete('/:id', (req, res) => {
    find(req.params.id);
    items.delete(req.params.id);
    res.status(204).end();
  });
  return router;
}

export function createApp() {
  const app = express();
  app.disable('x-powered-by');
  app.set('trust proxy', 'loopback');

  // Minimal security headers (no helmet).
  app.use((_req, res, next) => {
    res.set({
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'SAMEORIGIN',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
      'Cross-Origin-Opener-Policy': 'same-origin',
      'Content-Security-Policy': "default-src 'self'; img-src 'self' data:; frame-ancestors 'self'; base-uri 'self'",
    });
    next();
  });

  const api = express.Router();
  api.use(express.json({ limit: process.env.JSON_LIMIT || '100kb' }));
  api.get('/health', (_req, res) => res.json({ status: 'ok', uptime: Math.round(process.uptime()) }));
  api.use('/api/items', itemsRouter());
  api.use(express.static(fileURLToPath(new URL('./public', import.meta.url))));

  // Everything is mounted under BASE_PATH (or at / when unset).
  app.use(basePath || '/', api);

  app.use((req, _res, next) => next(new HttpError(404, 'not_found', `No route for ${req.method} ${req.path}`)));

  // Error envelope: { error: { code, message } }
  app.use((err, _req, res, _next) => {
    let status = err.status || err.statusCode || 500;
    let code = err.code || 'internal_error';
    let message = err.message;
    if (err.type === 'entity.parse.failed') code = 'invalid_json';
    else if (err.type === 'entity.too.large') code = 'payload_too_large';
    if (status >= 500) {
      console.error(err);
      status = 500;
      code = 'internal_error';
      message = 'Internal server error';
    }
    res.status(status).json({ error: { code: String(code), message } });
  });

  return app;
}

// Start only when run directly (tests import createApp).
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  const host = process.env.HOST || '0.0.0.0';
  const server = createApp().listen(port, host, () => {
    console.log(`API listening on http://${host}:${port}${basePath || ''}/`);
  });
  const shutdown = () => server.close(() => process.exit(0));
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}
EOF
