import { defineConfig } from 'vite';

// The workspace preview serves the app under /preview/<key>/ and passes BASE_PATH.
// Unset in production → '/'.
export default defineConfig({
  base: process.env.BASE_PATH || '/',
  // The preview is reached through the workspace proxy (foreign Host header) — allow it.
  server: { allowedHosts: true },
  preview: { allowedHosts: true },
});
import { defineConfig } from 'astro/config';

// The workspace preview serves the site under /preview/<key>/ and passes BASE_PATH, PORT and HOST.
// Astro wants the base without a trailing slash; unset in production → '/'.
const base = (process.env.BASE_PATH || '/').replace(/\/+$/, '') || '/';

export default defineConfig({
  output: 'static',
  base,
  server: {
    host: process.env.HOST || '0.0.0.0',
    port: Number(process.env.PORT) || 4321,
    // The preview is reached through the workspace proxy (foreign Host header) — allow it.
    allowedHosts: true,
  },
});
